import{_ as o,a0 as l,w as s,s as r,ao as m,I as p,x as n,a1 as t,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Cinnamon 2.8 新变化一览 | LCTT x X-CMD","titleTemplate":false,"description":"Cinnamon 2.8 新变化一览 | LCTT (201602) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Cinnamon 2.8 新变化一览 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Cinnamon 2.8 新变化一览 | LCTT (201602) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201602/20151201 Cinnamon 2.8 Review","title":"Cinnamon 2.8 新变化一览","tag":"201602","desc":""},"relativePath":"201602/20151201 Cinnamon 2.8 Review.md","filePath":"[post].md"}'),h={name:"201602/20151201 Cinnamon 2.8 Review.md"};function d(u,a,w,c,C,f){const e=l("Link");return s(),r("div",null,[a[13]||(a[13]=m(`<h1 id="cinnamon-2-8-新变化一览" tabindex="-1">Cinnamon 2.8 新变化一览 <a class="header-anchor" href="#cinnamon-2-8-新变化一览" aria-label="Permalink to “Cinnamon 2.8 新变化一览”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/11/cinnamon-2-8-featured.jpg" alt=""></p><p>除了Gnome和KDE外，Cinnamon是另一个很多人使用的桌面环境。它是由创作Linux Mint的团队制作的，并且可以被安装在许多其他发行版上。该桌面环境的最新版本 - Cinnamon 2.8 - 于去年底发布，此版本修复了许多的Bug、做了许多改进并添加了一些新功能。</p><p>我将仔细介绍该发行版本的主要改进，以及如何更新到Cinnamon 2.8或者第一次安装它。</p><h3 id="对applets的改进" tabindex="-1">对Applets的改进 <a class="header-anchor" href="#对applets的改进" aria-label="Permalink to “对Applets的改进”">​</a></h3><p>在此版本中，对面板中已有的Applets做了若干的改进。</p><h4 id="声音-applet" tabindex="-1">声音 Applet <a class="header-anchor" href="#声音-applet" aria-label="Permalink to “声音 Applet”">​</a></h4><p><img src="https://www.maketecheasier.com/assets/uploads/2015/11/rsz_cinnamon-28-sound-applet.jpg" alt="cinnamon-28-sound-applet"></p><p>声音Applet经过修正，目前可以显示音轨信息并且可以在音频文件的艺术家封面上面进行媒体控制。对于支持拖动的音乐播放器来说（例如Banshee），会有一个进度条显示同样的播放进度，您可以用它来改变音轨位置。在applet的面板上右击将显示对输入和输出设备静音的选项。</p><h4 id="电源-applet" tabindex="-1">电源 Applet <a class="header-anchor" href="#电源-applet" aria-label="Permalink to “电源 Applet”">​</a></h4><p>电源applet则会使用电池制造商的数据而不是通用名称来显示每一个连接的电池和设备。</p><h4 id="窗口缩略图" tabindex="-1">窗口缩略图 <a class="header-anchor" href="#窗口缩略图" aria-label="Permalink to “窗口缩略图”">​</a></h4><p><img src="https://www.maketecheasier.com/assets/uploads/2015/11/cinnamon-2.8-window-thumbnails.png" alt="cinnamon-2.8-window-thumbnails"></p><p>在Cinnamon 2.8中，可以在鼠标悬停于面板里窗口列表时展示窗口缩略图。如果您不喜欢该功能，您还可以关闭该选项。</p><h4 id="工作区切换-applet" tabindex="-1">工作区切换 Applet <a class="header-anchor" href="#工作区切换-applet" aria-label="Permalink to “工作区切换 Applet”">​</a></h4><p><img src="https://www.maketecheasier.com/assets/uploads/2015/11/cinnamon-2.8-workspace-switcher.png" alt="cinnamon-2.8-workspace-switcher"></p><p>添加工作区切换applet到您的面板将为您显示一个代表该工作区的可视化图像，一些矩形嵌套显示在其中，代表您的窗口的位置。</p><h4 id="系统托盘" tabindex="-1">系统托盘 <a class="header-anchor" href="#系统托盘" aria-label="Permalink to “系统托盘”">​</a></h4><p>Cinnamon 2.8支持在系统托盘中显示应用程序指示器。您可以很容易地在设置中禁用它，这将强制应用程序到以前使用状态图标的方式。</p><h3 id="视觉改进" tabindex="-1">视觉改进 <a class="header-anchor" href="#视觉改进" aria-label="Permalink to “视觉改进”">​</a></h3><p>Cinnamon 2.8还做了很多视觉上的改进。经典的切换器和Alt + Tab预览切换器都被精细打磨，有了显著的改进，同时修复了Alt + F2对话框的bug，并赋予了它更好的命令自动补全功能。</p><p>而且，传统的最小化窗口时动画效果的问题现已被解决，并可用于多个面板。</p><h3 id="nemo-的改进" tabindex="-1">Nemo 的改进 <a class="header-anchor" href="#nemo-的改进" aria-label="Permalink to “Nemo 的改进”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2015/11/rsz_cinnamon-28-nemo.jpg" alt="cinnamon-2.8-nemo"></p><p>Cinnamon默认的文件管理器也修复了一些bug，并有了新的“快速重命名”的功能，用于重命名文件和文件夹。可以通过两次点击文件或文件夹并在两次点击之间进行简短的停顿以重命名文件。</p><p>Nemo也会自动地检测缩略图存在的问题，并提示您快速地修复它们。</p><h3 id="其他值得注意的改进" tabindex="-1">其他值得注意的改进 <a class="header-anchor" href="#其他值得注意的改进" aria-label="Permalink to “其他值得注意的改进”">​</a></h3><ul><li>Applets如今会在它们被更新的时候自动地重新加载一次。</li><li>对于多个监视器的支持有了显著的提高。</li><li>对话框窗口有了改进，并且会附加到它的父窗口上。</li><li>HiDPI检测有了改进。</li><li>QT5应用程序现在看起来更加原生并使用了默认的GTK主题。</li><li>窗口管理和渲染性能有了提升。</li><li>修复了许多bug。</li></ul><h3 id="如何获得-cinnamon-2-8" tabindex="-1">如何获得 Cinnamon 2.8 <a class="header-anchor" href="#如何获得-cinnamon-2-8" aria-label="Permalink to “如何获得 Cinnamon 2.8”">​</a></h3><p>如果您在运行Linux Mint，您会在更新Linux Mint 17.3 “Rosa”Cinnamon版本的时候获得Cinnamon 2.8的更新。BETA版本现在已经放出，因此，如果您想立刻尝试新的软件，您可以试试。</p><p>对于Arch的用户来说，Cinnamon 2.8已经在Arch的官方仓库了，您可以通过更新软件包和系统级的更新获得Cinnamon的最新版本。</p><p>最后，对于Ubuntu用户来说，您可以通过下面的命令安装或更新Cinnamon 2.8：</p><pre><code>sudo add-apt-repository -y ppa:moorkai/cinnamon
sudo apt-get update
sudo apt-get install cinnamon
</code></pre><p>您已经尝试了Cinnamon 2.8了么？感觉如何呢？</p><hr>`,35)),p("p",null,[a[1]||(a[1]=n("via: ",-1)),t(e,{href:"https://www.maketecheasier.com/cinnamon-2-8-review/"},{default:i(()=>[...a[0]||(a[0]=[n("https://www.maketecheasier.com/cinnamon-2-8-review/",-1)])]),_:1})]),p("p",null,[a[5]||(a[5]=n("作者：",-1)),t(e,{href:"https://www.maketecheasier.com/author/ayoisaiah/"},{default:i(()=>[...a[2]||(a[2]=[n("Ayo Isaiah",-1)])]),_:1}),a[6]||(a[6]=n(" 译者：",-1)),t(e,{href:"https://github.com/wwy-hust"},{default:i(()=>[...a[3]||(a[3]=[n("wwy-hust",-1)])]),_:1}),a[7]||(a[7]=n(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[4]||(a[4]=[n("wxy",-1)])]),_:1})]),p("p",null,[a[10]||(a[10]=n("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[8]||(a[8]=[n("LCTT",-1)])]),_:1}),a[11]||(a[11]=n(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:i(()=>[...a[9]||(a[9]=[n("Linux中国",-1)])]),_:1}),a[12]||(a[12]=n(" 荣誉推出",-1))])])}const k=o(h,[["render",d]]);export{T as __pageData,k as default};
